function longestCommonPrefix(strs) {
  const sorted = [...strs].sort();            // the first and last words differ the most
  const first = sorted[0], last = sorted[sorted.length - 1];
  let i = 0;
  while (i < first.length && first[i] === last[i]) i++;
  return first.slice(0, i);                   // what they share, everyone shares
}

String longestCommonPrefix(String[] strs) {
    String[] sorted = strs.clone();
    Arrays.sort(sorted);                         // the first and last words differ the most
    String first = sorted[0], last = sorted[sorted.length - 1];
    int i = 0;
    while (i < first.length() && i < last.length() && first.charAt(i) == last.charAt(i)) i++;
    return first.substring(0, i);                // what they share, everyone shares
}

string longestCommonPrefix(vector<string> strs) {   // a copy, so sorting is harmless
    sort(strs.begin(), strs.end());              // the first and last words differ the most
    const string& first = strs.front();
    const string& last = strs.back();
    size_t i = 0;
    while (i < first.size() && i < last.size() && first[i] == last[i]) i++;
    return first.substr(0, i);                   // what they share, everyone shares
}

function longestCommonPrefix(strs) {
  const first = strs[0];
  for (let i = 0; i < first.length; i++) {    // column i
    for (const word of strs) {
      if (i === word.length || word[i] !== first[i]) {
        return first.slice(0, i);             // a word ended or disagreed: stop here
      }
    }
  }
  return first;                               // the whole first word is shared
}

def longest_common_prefix(strs):
    first = strs[0]
    for i in range(len(first)):           # column i
        for word in strs:
            if i == len(word) or word[i] != first[i]:
                return first[:i]          # a word ended or disagreed: stop here
    return first                          # the whole first word is shared

String longestCommonPrefix(String[] strs) {
    String first = strs[0];
    for (int i = 0; i < first.length(); i++) {   // column i
        for (String word : strs) {
            if (i == word.length() || word.charAt(i) != first.charAt(i)) {
                return first.substring(0, i);    // a word ended or disagreed: stop here
            }
        }
    }
    return first;                                // the whole first word is shared
}

